// Tinted dark surfaces guard.
//
// `src/styles/variables/_tinted-dark.scss` is generated by
// `scripts/build-tinted-dark.mjs`, and `app-theme()` emits it under
// `[data-nb-dark-surfaces='tinted']`. This file holds both ends: the committed
// file has to be exactly what the generator writes today, and what ships, read
// back out of the compiled CSS, has to clear the same bars the grey ramp does.
//
// The tint holds WCAG relative luminance, so in principle every ratio is the
// grey ramp's. In practice 8-bit rounding moves each value by a fraction of a
// step, and that is what these measurements are for.

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import * as sass from 'sass-embedded'
import {
  ROOT,
  lstar,
  lum,
  loadThemeResolvers,
  parseColor,
  propsFrom,
  ratio,
  resolver,
} from '../scripts/lib/layerTokens.mjs'
import {
  OUT_FILE,
  readCategories,
  readDarkRamp,
  renderTintedDark,
} from '../scripts/build-tinted-dark.mjs'

const AAA = 7
const AA = 4.5
/** How far a tinted step may drift from the grey ramp's step, in CIE L*. */
const MAX_STEP_DRIFT = 0.5

const LEVELS = [0, 1, 2, 3] as const

/** The status foregrounds the library draws as text or marks on a dark plane. */
const STATUS = [
  'status-valid',
  'status-warning',
  'status-error',
  'status-info',
  'text-error',
  'text-warning',
] as const

const FLAG = '[data-nb-dark-surfaces=tinted]'
const CATEGORIES = Object.keys(readCategories())
const RAMP = readDarkRamp()
const grey = loadThemeResolvers().dark

/** Compiles one app theme and returns its CSS. */
function compileApp(id: string, category: string): string {
  return sass.compileString(
    `@use 'theme-api' as nb;\n@include nb.app-theme('${id}', $category: '${category}');`,
    { loadPaths: [resolve(ROOT, 'src/styles')], style: 'compressed' },
  ).css
}

/** The plain tinted scope's declarations: the first of the four selectors. */
function tintedProps(css: string, id: string): Record<string, string> {
  const esc = FLAG.replace(/[[\]]/g, '\\$&')
  return propsFrom(
    css,
    new RegExp(`^${esc}\\.dark\\[data-nb-theme=["']?${id}["']?\\],`),
  )
}

const lumOf = (hex: string) => lum(parseColor(hex) as number[])

describe('the generated file', () => {
  it('is byte-identical to what the generator writes from the current source', async () => {
    const committed = readFileSync(OUT_FILE, 'utf8')
    const next = await renderTintedDark()
    expect(
      committed === next,
      'src/styles/variables/_tinted-dark.scss is out of date: run pnpm run generate:tinted-dark',
    ).toBe(true)
  })
})

describe('tinted dark surfaces clear the grey ramp bars', () => {
  const greySurface = LEVELS.map((i) => grey(`--nb-c-layer-${i}`) as string)
  const greySteps = [0, 1, 2].map(
    (i) => lstar(greySurface[i + 1]) - lstar(greySurface[i]),
  )

  for (const category of CATEGORIES) {
    const id = `probe-${category}`
    const css = compileApp(id, category)
    const props = tintedProps(css, id)
    const get = resolver([props])
    const surface = LEVELS.map((i) => get(`--nb-c-layer-${i}`) as string)

    it(`${category}: every surface is tinted, not grey`, () => {
      for (const [i, value] of surface.entries()) {
        expect(parseColor(value), `layer-${i} ${value}`).toBeTruthy()
        expect(value).not.toBe(greySurface[i])
      }
    })

    it(`${category}: text and muted reach 7:1, subtle 4.5:1, on all four surfaces`, () => {
      for (const [tier, min] of [
        ['text', AAA],
        ['text-muted', AAA],
        ['text-subtle', AA],
      ] as const) {
        const fg = get(`--nb-c-${tier}`) as string
        for (const [i, bg] of surface.entries()) {
          const r = ratio(fg, bg) as number
          expect(
            r,
            `${category} ${tier} ${fg} on layer-${i} ${bg} is ${r.toFixed(3)}:1`,
          ).toBeGreaterThanOrEqual(min)
        }
      }
    })

    it(`${category}: status foregrounds reach 4.5:1 on layers 0 and 1`, () => {
      for (const role of STATUS) {
        const fg = grey(`--nb-c-${role}`) as string
        expect(parseColor(fg), `${role} resolved to ${fg}`).toBeTruthy()
        for (const i of [0, 1]) {
          const r = ratio(fg, surface[i]) as number
          expect(
            r,
            `${category} ${role} ${fg} on layer-${i} ${surface[i]} is ${r.toFixed(3)}:1`,
          ).toBeGreaterThanOrEqual(AA)
        }
      }
    })

    it(`${category}: depth steps stay within ${MAX_STEP_DRIFT} dL* of the grey ramp`, () => {
      for (let i = 0; i < 3; i++) {
        const step = lstar(surface[i + 1]) - lstar(surface[i])
        expect(
          Math.abs(step - greySteps[i]),
          `${category} layer-${i} to layer-${i + 1}: ${step.toFixed(2)} vs grey ${greySteps[i].toFixed(2)}`,
        ).toBeLessThanOrEqual(MAX_STEP_DRIFT)
      }
    })

    // The rounding rule that keeps every pair from getting worse: a
    // surface, border or hover never lighter than its grey, a text tier
    // never darker.
    it(`${category}: rounds every value to the safe side of its grey`, () => {
      for (const [role, values] of Object.entries(RAMP.levels)) {
        for (const i of LEVELS) {
          const name =
            role === 'surface'
              ? `--nb-c-layer-${i}`
              : `--nb-c-layer-${role}-${i}`
          const tinted = get(name)
          expect(tinted, `${name} is not declared`).toBeTruthy()
          expect(lumOf(tinted as string), name).toBeLessThanOrEqual(
            lumOf(values[i]),
          )
        }
      }
      for (const tier of ['text', 'text-muted', 'text-subtle']) {
        expect(lumOf(get(`--nb-c-${tier}`) as string)).toBeGreaterThanOrEqual(
          lumOf(RAMP.scalars[tier]),
        )
      }
    })

    it(`${category}: re-declares every value the dark theme takes from the ramp`, () => {
      const dark = propsFrom(
        sass.compileString(`@use 'theme'; @include theme.dark;`, {
          loadPaths: [resolve(ROOT, 'src/styles')],
          style: 'compressed',
        }).css,
        /^\.dark$/,
      )
      const greys = new Set(
        [
          ...Object.values(RAMP.levels).flat(),
          ...Object.values(RAMP.scalars),
        ].map((v) => v.toLowerCase()),
      )
      const fromRamp = Object.entries(dark)
        .filter(
          ([, v]) =>
            greys.has(v.toLowerCase()) || /^var\(--nb-c-layer-/.test(v),
        )
        .map(([k]) => k)
      expect(fromRamp.length).toBeGreaterThan(60)
      for (const name of fromRamp)
        expect(props, `${name} is not re-declared`).toHaveProperty(name)
    })

    // Off by default: every rule that carries the tint names the flag in
    // every one of its selectors, so a document without it is untouched.
    it(`${category}: nothing tinted applies without the flag`, () => {
      const rules = [...css.matchAll(/([^{}]*)\{[^{}]*\}/g)]
      const tinted = rules.filter(([, sel]) =>
        sel.includes('data-nb-dark-surfaces'),
      )
      expect(tinted.length).toBeGreaterThan(0)
      for (const [, sel] of tinted)
        for (const one of sel.split(','))
          expect(one, `selector without the flag: ${one}`).toContain(FLAG)
    })
  }
})
